package com.fasterxml.jackson.databind.introspect;

import com.fasterxml.jackson.annotation.JsonIdentityInfo;
import com.fasterxml.jackson.annotation.JsonProperty;
import com.fasterxml.jackson.annotation.ObjectIdGenerator;
import com.fasterxml.jackson.annotation.ObjectIdResolver;
import com.fasterxml.jackson.annotation.SimpleObjectIdResolver;
import com.fasterxml.jackson.databind.PropertyName;
import com.fasterxml.jackson.databind.introspect.ObjectIdGenerator;
import com.fasterxml.jackson.databind.introspect.ObjectIdResolver;
import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for ObjectIdInfo constructor and associated getter methods.
 */
public class ObjectIdInfo_ObjectIdInfo_TriageGen1Test {

    // Mock classes to satisfy generic constraints
    public static class MockGenerator extends ObjectIdGenerator<String> {
        @Override
        public String generate(Object prefix) {
            return null;
        }
    }

    public static class MockResolver implements ObjectIdResolver {
        @Override
        public ObjectIdGenerator resolveId(Object id) { return null; }
        @Override
        public boolean isTypeResolvable(Class<?> type) { return false; }
        @Override
        public ObjectIdGenerator resolveId(Object id, Class<?> type) { return null; }
    }

    public static class MockScope {}

    @Test
    public void testConstructorAndGetters() {
        // Arrange
        PropertyName name = PropertyName.construct("id", false);
        Class<?> scope = MockScope.class;
        Class<? extends ObjectIdGenerator<?>> gen = MockGenerator.class;
        Class<? extends ObjectIdResolver> resolver = MockResolver.class;

        // Act
        ObjectIdInfo info = new ObjectIdInfo(name, scope, gen, resolver);

        // Assert
        Assert.assertEquals(name, info.getPropertyName());
        Assert.assertEquals(scope, info.getScope());
        Assert.assertEquals(gen, info.getGeneratorType());
        Assert.assertEquals(resolver, info.getResolverType());
        // The constructor calls this(name, scope, gen, false, resolver), so alwaysAsId should be false
        Assert.assertFalse(info.getAlwaysAsId());
    }

    @Test
    public void testWithAlwaysAsId() {
        // Arrange
        PropertyName name = PropertyName.construct("id", false);
        Class<?> scope = MockScope.class;
        Class<? extends ObjectIdGenerator<?>> gen = MockGenerator.class;
        Class<? extends ObjectIdResolver> resolver = MockResolver.class;
        ObjectIdInfo info = new ObjectIdInfo(name, scope, gen, resolver);

        // Act
        ObjectIdInfo updatedInfo = info.withAlwaysAsId(true);

        // Assert
        Assert.assertTrue(updatedInfo.getAlwaysAsId());
        // Ensure immutability/consistency of other properties
        Assert.assertEquals(name, updatedInfo.getPropertyName());
        Assert.assertEquals(scope, updatedInfo.getScope());
        Assert.assertEquals(gen, updatedInfo.getGeneratorType());
        Assert.assertEquals(resolver, updatedInfo.getResolverType());
    }

    @Test
    public void testToString() {
        // Arrange
        PropertyName name = PropertyName.construct("id", false);
        Class<?> scope = MockScope.class;
        Class<? extends ObjectIdGenerator<?>> gen = MockGenerator.class;
        Class<? extends ObjectIdResolver> resolver = MockResolver.class;
        ObjectIdInfo info = new ObjectIdInfo(name, scope, gen, resolver);

        // Act
        String toStringResult = info.toString();

        // Assert
        Assert.assertNotNull(toStringResult);
        // toString typically contains class name and field values
        Assert.assertTrue(toStringResult.contains("ObjectIdInfo"));
    }
}
